namespace ghidra.framework.main.datatree;

using ghidra.framework.client;
using ghidra.framework.main;
using ghidra.framework.model;
using ghidra.framework.model;
using ghidra.util;
using ghidra.util.exception;
using ghidra.util.task;
using ghidra.util.task;



class CopyFileVersionTask : Task {

	private DomainFile file;
	private int version;
	private DomainFolder destFolder;

	CopyFileVersionTask(DomainFile file, int version, DomainFolder destFolder) : base("Copy File Version", true, true, true)
    {
		this.file = file;
		this.version = version;
		this.destFolder = destFolder;
	}

	/* @Override */
	public void run(TaskMonitor monitor) {
		try {
			monitor.setMessage("Copying " + file.getName() + " version " + version + "...");
			if (file.copyVersionTo(version, destFolder, monitor) == null) {
				Msg.showError(this, null, "Version Copy Failed", "Failed to copy file version");
			}
		} catch (CancelledException e) {
		} catch (IOException e) {
			ClientUtil.handleException(AppInfo.getActiveProject().getRepository(), e, "Version Copy",
				null);
		}
	}

}
